import{_ as a,o as i,c as t,aw as e}from"./chunks/framework.DLufY-ao.js";const S=JSON.parse('{"title":"XSS","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/network/network/hacking/xss.md","filePath":"wiki/dev-commit/network/network/hacking/xss.md"}'),o={name:"wiki/dev-commit/network/network/hacking/xss.md"};function r(s,l,c,n,h,u){return i(),t("div",null,[...l[0]||(l[0]=[e('<h1 id="xss" tabindex="-1">XSS <a class="header-anchor" href="#xss" aria-label="Permalink to &quot;XSS&quot;">​</a></h1><ul><li><strong>XSS</strong> (Cross-Site Scripting / Межсайтовый скриптинг) - вид атаки, при которой в страницу сайта внедряется вредоносный код</li><li>При открытии страницы пользователем, код выполняется на его компьютере и устанавливает соединение с веб-сервером злоумышленника, который таким образом получает контроль над системой</li><li>Основная цель злоумышленника - запустить вредоносный скрипт на компьютере жертвы</li></ul><h2 id="на-что-нацелен" tabindex="-1">На что нацелен <a class="header-anchor" href="#на-что-нацелен" aria-label="Permalink to &quot;На что нацелен&quot;">​</a></h2><ul><li>Кража конфиденциальных данных, переадресацию пользователя на подконтрольные хакерам сайты или на манипуляцию компьютера в интересах злоумышленников</li><li>Кража cookies пользователей при помощи встроенного на сервере скрипта с дальнейшей выборкой необходимых данных и использованием их для последующих атак и взломов</li></ul><h2 id="общая-классификация-xss" tabindex="-1">Общая классификация XSS <a class="header-anchor" href="#общая-классификация-xss" aria-label="Permalink to &quot;Общая классификация XSS&quot;">​</a></h2><h3 id="_1-хранимые-xss-постоянные" tabindex="-1">1. Хранимые XSS (постоянные) <a class="header-anchor" href="#_1-хранимые-xss-постоянные" aria-label="Permalink to &quot;1. Хранимые XSS (постоянные)&quot;">​</a></h3><ul><li>Один из самых опасных типов уязвимостей, так как позволяет злоумышленнику получить доступ к серверу и уже с него управлять вредоносным кодом (удалять, модифицировать)</li><li>Каждый раз при обращении к сайту выполняется заранее загруженный код, работающий в автоматическом режиме. В основном таким уязвимостям подвержены форумы, порталы, блоги, где присутствует возможность комментирования в HTML без ограничений. Вредоносные скрипты с легкостью могут быть встроены как в текст, так и в картинки, рисунки.</li></ul><h3 id="_2-отраженные-xss-непостоянные" tabindex="-1">2. Отраженные XSS (непостоянные) <a class="header-anchor" href="#_2-отраженные-xss-непостоянные" aria-label="Permalink to &quot;2. Отраженные XSS (непостоянные)&quot;">​</a></h3><ul><li>В этом случае вредоносная строчка выступает в роли запроса жертвы к зараженному веб-сайту</li></ul><ol><li>Злоумышленник заранее создает URL-ссылку, которая будет содержать вредоносный код и отправляет его своей жертве</li><li>Она направляет этот URL-запрос на сайт (переходит по ссылке)</li><li>Сайт автоматически берет данные из вредоносной строки и подставляет в виде модифицированного URL-ответа жертве</li><li>В итоге в браузере у жертвы выполняется вредоносный скрипт, который и содержится в ответе, а злоумышленник получает все cookies этого пользователя</li></ol><h3 id="_3-dom-модели" tabindex="-1">3. DOM-модели <a class="header-anchor" href="#_3-dom-модели" aria-label="Permalink to &quot;3. DOM-модели&quot;">​</a></h3><ul><li>В этом варианте возможно использование как хранимых XSS, так и отраженных</li></ul><ol><li>Злоумышленник создает URL-адрес, который заранее содержит вредоносный код, и отправляет его по электронной почте или любым другим способом пользователю</li><li>Человек переходит по этой ссылке, зараженный сайт принимает запрос, исключая вредоносную строку</li><li>На странице у пользователя выполняется сценарий, в результате чего загружается вредоносный скрипт и злоумышленник получает cookies</li></ol><h2 id="виды-xss-по-способу-взаимодеиствия" tabindex="-1">Виды XSS по способу взаимодействия <a class="header-anchor" href="#виды-xss-по-способу-взаимодеиствия" aria-label="Permalink to &quot;Виды XSS по способу взаимодействия&quot;">​</a></h2><h3 id="_1-пассивные" tabindex="-1">1. Пассивные <a class="header-anchor" href="#_1-пассивные" aria-label="Permalink to &quot;1. Пассивные&quot;">​</a></h3><ul><li><p>Код встраивается в определенную страницу, на которую пользователь привлекается, к примеру, с помощью фишинга</p></li><li><p>Суть: заставить пользователя перейти по вредоносной ссылке для выполнения «вредокода»</p></li><li><p><strong>Фишинг</strong> - форма киберпреступности, основанная на методах социальной инженерии. Предполагает кражу конфиденциальных данных с компьютера пользователя и использование этих данных для получения его денег. Мошенник создает, например, копию сайта финансового учреждения или онлайн-магазина и пытается заманить туда пользователя, чтобы заставить его ввести свои имя, пароль, номер кредитной карточки и т.д.</p></li></ul><h3 id="_2-активные" tabindex="-1">2. Активные <a class="header-anchor" href="#_2-активные" aria-label="Permalink to &quot;2. Активные&quot;">​</a></h3><ul><li>Код внедряется на уровне базы данных или исполняемом файле на сервере</li><li>От пользователя не требуется никакой активности. У форм ввода, как правило, установлен специальный обработчик событий, автоматически активирующийся при попадании на эту страничку</li><li>В итоге все пользователи, перешедшие по этой ссылке, станут жертвами злоумышленника</li><li>Хакер пытается найти уязвимость в фильтре сайта: при помощи комбинации тегов и символов создается такой запрос, чтобы сайт его понял и выполнил команду</li></ul><h2 id="методика-атаки-через-xss" tabindex="-1">Методика атаки через XSS <a class="header-anchor" href="#методика-атаки-через-xss" aria-label="Permalink to &quot;Методика атаки через XSS&quot;">​</a></h2><ul><li>Запуск вредоносного кода JavaScript возможен только в браузере жертвы, поэтому сайт, на который зайдет пользователь, должен иметь уязвимость к XSS</li></ul><h3 id="вариант-1" tabindex="-1">Вариант 1 <a class="header-anchor" href="#вариант-1" aria-label="Permalink to &quot;Вариант 1&quot;">​</a></h3><ul><li><ol><li>Для совершения атаки злоумышленник изначально проверяет ресурсы на наличие уязвимостей через XSS, используя автоматизированные скрипты или ручной режим поиска. Обычно это стандартные формы, которые могут отправлять и принимать запросы (комментарии, поиск, обратная связь)</li></ol></li><li><ol start="2"><li>Проводится полный сбор страниц с формами ввода, и каждая сканируется на наличие уязвимостей. Например, у нас есть страница «Поиск» на сайте. Для проверки уязвимости XSS достаточно ввести запрос: <code>&lt;script&gt;alert(&quot;cookie: &quot;+document.cookie)&lt;/script&gt;</code></li></ol></li><li>Если на экране появится уведомление, значит вы обнаружили брешь в безопасности. В противном случае система отобразит вам страницу с результатами поиска</li></ul><h3 id="вариант-2-использование-страниц-которые-обрабатывают-get-запросы" tabindex="-1">Вариант 2: использование страниц, которые обрабатывают GET-запросы <a class="header-anchor" href="#вариант-2-использование-страниц-которые-обрабатывают-get-запросы" aria-label="Permalink to &quot;Вариант 2: использование страниц, которые обрабатывают GET-запросы&quot;">​</a></h3><ul><li>Допустим, у нас есть ссылка вида: <a href="http://site.ru/catalog?p=8" target="_blank" rel="noreferrer">http://site.ru/catalog?p=8</a></li><li>В адресной строке вместо идентификатора (8) добавляем скрипт – <code>&lt;script&gt;alert(&quot;cookie: &quot;+document.cookie)&lt;/script&gt;</code>, в результате чего получаем ссылку такого вида: <a href="http://site.ru/catalog?p=" target="_blank" rel="noreferrer">http://site.ru/catalog?p=</a>&quot; <code>&lt;script&gt;alert(&quot;cookie: &quot;+document.cookie)&lt;/script&gt;</code></li><li>Если страница имеет уязвимости XSS, на экране появится уведомление такого же плана, как и в первом случае</li></ul><h2 id="предотвращение" tabindex="-1">Предотвращение <a class="header-anchor" href="#предотвращение" aria-label="Permalink to &quot;Предотвращение&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p><a href="http://xss-scanner.com/" target="_blank" rel="noreferrer">http://xss-scanner.com/</a></p></div><ol><li>Фильтрация получаемых данных</li><li>В обязательном порядке нужно проверять все URL, где возможна отправка данных со стороны пользователя (формы комментариев, обратная связь, поиск)</li><li>Исключить все опасные спецсимволы, заменив их безопасными. Речь идет о скобках &lt; и &gt;, в которых и прописываются все зарезервированные языком html-запросы и теги</li></ol>',27)])])}const k=a(o,[["render",r]]);export{S as __pageData,k as default};
